    "\tplanned_worst_case_loss NUMERIC NOT NULL, \n"
    "\tplanned_collateral NUMERIC NOT NULL, \n"
    "\tplanned_open_order_slots BIGINT NOT NULL, \n"
    "\tplanned_pending_rate_units BIGINT NOT NULL, \n"
