    "\trate_window_start_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\trate_window_end_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\tremaining_contracts BIGINT NOT NULL, \n"
    "\tremaining_incremental_gross_exposure NUMERIC NOT NULL, \n"
    "\tremaining_worst_case_loss NUMERIC NOT NULL, \n"
    "\tremaining_collateral NUMERIC NOT NULL, \n"
    "\tremaining_open_order_slots BIGINT NOT NULL, \n"
