    "('PRIVATE','UNRESOLVED') AND (route_family <> 'PRIVATE' OR region = 'india'))) AND (call_kind <> "
    "'DISPATCH' OR ((operation = 'PLACE_ORDER' AND route_id = 'place_order') OR (operation = "
    "'MODIFY_ORDER' AND route_id = 'modify_order'))) AND ((route_family = 'PUBLIC' AND route_id = "
    "'products' AND method = 'GET' AND path_template = '/v2/products' AND policy_version = "
    "'delta-docs-2026-11-03' AND weight = 3) OR (route_family = 'PUBLIC' AND route_id = 'product' AND "
    "method = 'GET' AND path_template = '/v2/products/{symbol}' AND policy_version = "
    "'delta-docs-2026-11-03' AND weight = 3) OR (route_family = 'PUBLIC' AND route_id = 'tickers' AND "
    "method = 'GET' AND path_template = '/v2/tickers' AND policy_version = 'delta-docs-2026-11-03' "
    "AND weight = 3) OR (route_family = 'PUBLIC' AND route_id = 'ticker' AND method = 'GET' AND "
    "path_template = '/v2/tickers/{symbols}' AND policy_version = 'delta-docs-2026-11-03' AND weight "
    "= 3) OR (route_family = 'PUBLIC' AND route_id = 'orderbook' AND method = 'GET' AND path_template "
    "= '/v2/l2orderbook/{symbol}' AND policy_version = 'delta-docs-2026-11-03' AND weight = 3) OR "
    "(route_family = 'PUBLIC' AND route_id = 'candles' AND method = 'GET' AND path_template = "
