    "(route_family = 'PRIVATE' AND route_id = 'balances' AND method = 'GET' AND path_template = "
    "'/v2/wallet/balances' AND policy_version = 'delta-docs-2026-11-04-private-v1' AND weight = 3) OR "
    "(route_family = 'PRIVATE' AND route_id = 'transactions' AND method = 'GET' AND path_template = "
    "'/v2/wallet/transactions' AND policy_version = 'delta-docs-2026-11-04-private-v1' AND weight = "
    "10) OR (route_family = 'PRIVATE' AND route_id = 'margined_positions' AND method = 'GET' AND "
