    "\tCONSTRAINT ck_api_audit_events_completed_response_byte_length_sign_c262 CHECK "
    "(completed_response_byte_length IS NULL OR completed_response_byte_length BETWEEN "
    "-9223372036854775808 AND 9223372036854775807), \n"
    "\tCONSTRAINT ck_api_audit_events_duration_ns_signed_bigint CHECK (duration_ns IS NULL OR "
