    "\tCONSTRAINT ck_api_audit_events_retention_policy_version_signed_bigint CHECK "
    "(retention_policy_version IS NULL OR retention_policy_version BETWEEN -9223372036854775808 AND "
    "9223372036854775807), \n"
    "\tCONSTRAINT ck_api_audit_events_source_payload_schema_version_signed_bigint CHECK "
    "(source_payload_schema_version IS NULL OR source_payload_schema_version BETWEEN "
    "-9223372036854775808 AND 9223372036854775807), \n"
    "\tCONSTRAINT ck_api_audit_events_source_payload_byte_length_signed_bigint CHECK "
    "(source_payload_byte_length IS NULL OR source_payload_byte_length BETWEEN -9223372036854775808 "
