    "\tCONSTRAINT ck_api_audit_events_source_payload_ttl_seconds_signed_bigint CHECK "
    "(source_payload_ttl_seconds IS NULL OR source_payload_ttl_seconds BETWEEN -9223372036854775808 "
    "AND 9223372036854775807), \n"
    "\tCONSTRAINT ck_api_audit_events_source_retention_policy_version_sig_c733 CHECK "
    "(source_retention_policy_version IS NULL OR source_retention_policy_version BETWEEN "
    "-9223372036854775808 AND 9223372036854775807), \n"
    "\tCONSTRAINT ck_api_audit_events_actor_role_oid_signed_bigint CHECK (actor_role_oid IS NULL OR "
    "actor_role_oid BETWEEN -9223372036854775808 AND 9223372036854775807), \n"
    "\tCONSTRAINT ck_api_audit_events_policy_version_optional_bounded CHECK (policy_version IS NULL "
    "OR (length(policy_version) BETWEEN 1 AND 128 AND length(trim(policy_version)) > 0)), \n"
    "\tCONSTRAINT ck_api_audit_events_route_id_optional_bounded CHECK (route_id IS NULL OR "
    "(length(route_id) BETWEEN 1 AND 128 AND length(trim(route_id)) > 0)), \n"
    "\tCONSTRAINT ck_api_audit_events_method_optional_bounded CHECK (method IS NULL OR "
