def upgrade() -> None:
    """Create the exact frozen private application schema."""

    for statement in UPGRADE_STATEMENTS:
        op.execute(sa.text(statement))


def downgrade() -> None:
    """Remove only an explicitly acknowledged, empty development schema."""

    if os.environ.get("HMT_CRYPTO_ALLOW_EMPTY_DOWNGRADE") != DOWNGRADE_ACK:
        raise RuntimeError("Downgrade is restricted to an acknowledged empty development database")
    op.execute(sa.text(EMPTY_SCHEMA_GUARD))
    for statement in DOWNGRADE_STATEMENTS:
        op.execute(sa.text(statement))
